-- =============================================================================
-- RE-IMPORT MAIO/2026 — versão 100% fiel às 3 planilhas
--
-- 1) Apaga TODOS os shifts de maio/2026 (mantém escalas e profissionais)
-- 2) Re-insere usando mapeamento explícito de nomes abreviados
-- 3) Para duplicatas no banco (mesmo nome, IDs diferentes), pega só UM
--    para evitar inflar a contagem
-- =============================================================================

CREATE OR REPLACE FUNCTION norm_name(s text) RETURNS text AS $$
  SELECT lower(translate(s,
    'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ',
    'aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'));
$$ LANGUAGE SQL IMMUTABLE;

-- 1) Apaga shifts de maio/2026 (e respectivos shift_swaps via FK)
WITH ids AS (
  SELECT s.id FROM shifts s
  JOIN monthly_schedules ms ON ms.id = s.schedule_id
  WHERE EXTRACT(year FROM ms.month) = 2026 AND EXTRACT(month FROM ms.month) = 5
)
DELETE FROM shift_swaps
WHERE original_shift_id IN (SELECT id FROM ids)
   OR offered_shift_id IN (SELECT id FROM ids);

DELETE FROM shifts s
USING monthly_schedules ms
WHERE s.schedule_id = ms.id
  AND EXTRACT(year FROM ms.month) = 2026
  AND EXTRACT(month FROM ms.month) = 5;

