prof_resolved AS (
  SELECT
    i.sector, i.db_name, i.day, i.shift_type, i.start_t, i.end_t,
    (SELECT p.id FROM professionals p
     WHERE norm_name(p.full_name) = norm_name(i.db_name)
       AND p.active = true
     ORDER BY p.created_at
     LIMIT 1) AS prof_id
  FROM imported i
)
INSERT INTO shifts (
  professional_id, schedule_id, department_id,
  shift_date, shift_type, start_time, end_time
)
SELECT
  pr.prof_id,
  ms.id,
  d.id,
  make_date(2026, 5, pr.day),
  pr.shift_type,
  pr.start_t,
  pr.end_t
FROM prof_resolved pr
JOIN departments d ON d.name = pr.sector
JOIN monthly_schedules ms ON ms.department_id = d.id AND ms.month = '2026-05-01'::date
WHERE pr.prof_id IS NOT NULL;

-- 3) Verificação: totais por setor (esperado: Enf=181, CME=26, Téc=689, total=896)
SELECT
  d.name AS setor,
  COUNT(*) AS total
FROM shifts s
JOIN monthly_schedules ms ON ms.id = s.schedule_id
JOIN departments d ON d.id = ms.department_id
WHERE EXTRACT(year FROM ms.month) = 2026 AND EXTRACT(month FROM ms.month) = 5
GROUP BY d.name
ORDER BY d.name;

-- 4) Total geral
SELECT COUNT(*) AS total_geral
FROM shifts s
JOIN monthly_schedules ms ON ms.id = s.schedule_id
WHERE EXTRACT(year FROM ms.month) = 2026 AND EXTRACT(month FROM ms.month) = 5;

